# Context Window Overflow — Chunking Strategy

MAX_TOKENS = 3800  # Model limit: 4096 - 200 buffer - 96 system
OVERLAP = 0.15     # 15% overlap to prevent entity splitting

def chunk_document(tokens: list[str]) -> list[list[str]]:
    chunks = []
    step = int(MAX_TOKENS * (1 - OVERLAP))
    for i in range(0, len(tokens), step):
        chunk = tokens[i:i + MAX_TOKENS]
        chunks.append(chunk)
    return chunks

def merge_extractions(results: list[dict]) -> dict:
    seen = {}
    for r in results:
        for entity in r['entities']:
            key = entity['name'].lower()
            if key not in seen or levenshtein(key, seen[key]) < 3:
                seen[key] = entity
    return list(seen.values())

// WebSocket Reconnection — Jittered Exponential Backoff

class ResilientSocket {
  constructor(url) {
    this.url = url;
    this.attempt = 0;
    this.maxDelay = 30000;
    this.connect();
  }

  getDelay() {
    const base = Math.min(500 * Math.pow(2, this.attempt), this.maxDelay);
    const jitter = base * (0.6 + Math.random() * 0.8); // ±40%
    return Math.round(jitter);
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onopen = () => { this.attempt = 0; };
    this.ws.onclose = () => {
      const delay = this.getDelay();
      this.attempt++;
      console.log(`[WS] Retry #${this.attempt} in ${delay}ms`);
      setTimeout(() => this.connect(), delay);
    };
  }
}
